static String captureConsoleOutput(Runnable action) throws IOException {
    File tempFile = File.createTempFile("capture", ".txt");
    PrintStream original = System.out;
    try (PrintStream fileOut = new PrintStream(tempFile)) {
        System.setOut(fileOut);
        action.run();
    } finally {
        System.setOut(original);
    }
    String result = Files.readString(tempFile.toPath());
    tempFile.delete();
    return result;
}

