static void testFunction(Runnable functionUnderTest, String expectedOutput) throws IOException {
    File tempFile = File.createTempFile("test", ".txt");
    PrintStream original = System.out;
    try (PrintStream fileOut = new PrintStream(tempFile)) {
        System.setOut(fileOut);
        functionUnderTest.run();
    } finally {
        System.setOut(original);
    }
    String actual = Files.readString(tempFile.toPath()).trim();
    tempFile.delete();
    System.out.println(actual.equals(expectedOutput) ? "PASS" : "FAIL (got: '" + actual + "')");
}

