static PrintWriter logWriter;
static boolean fallbackToConsole = false;

static void safeLog(String msg) {
    if (!fallbackToConsole) {
        logWriter.println(msg);
        if (logWriter.checkError()) {
            fallbackToConsole = true;
            System.out.println("[FALLBACK] " + msg);
        }
    } else {
        System.out.println("[FALLBACK] " + msg);
    }
}

