File outFile = new File(System.getProperty("java.io.tmpdir"), "out30.txt");
File errFile = new File(System.getProperty("java.io.tmpdir"), "err30.txt");
PrintStream originalOut = System.out;
PrintStream originalErr = System.err;

try (PrintStream fileOut = new PrintStream(outFile);
     PrintStream fileErr = new PrintStream(errFile)) {
    System.setOut(fileOut);
    System.setErr(fileErr);
    try {
        System.out.println("Przed wyjatkiem");
        throw new RuntimeException("Testowy wyjatek");
